{
  "_comment": "RFC module. Not callable from Postman. Field contract below.",
  "_evidence": "DOC_TYPE=UB executed with TESTRUN=X on DS4 2026-08-19. Cleared document-type validation (no ME 013). Failed only on DS4 data: ME 083 purchasing group, 06 166 plant currency, M3 351 material not in receiving plant. ZP06 is a UB copy (T161 BREFN=UBF) so it takes the same path, but ZP06 itself has NOT been executed - DS4 does not have it.",

  "POHEADER": {
    "COMP_CODE":  "1000",
    "DOC_TYPE":   "ZP06",
    "PURCH_ORG":  "1000",
    "PUR_GROUP":  "801",
    "SUPPL_PLNT": "<supplying plant>",
    "VENDOR":     "",
    "_note": "VENDOR STAYS EMPTY. Confirmed on all 15 live ZP06 STOs in QS4 - EKKO-LIFNR is blank. An STO has a supplying plant (EKKO-RESWK), not a vendor. SUPPL_PLNT is off-screen in SE37; use Column/Position (Ctrl+Shift+F8) to reach it."
  },

  "POHEADERX": {
    "COMP_CODE": "X", "DOC_TYPE": "X", "PURCH_ORG": "X", "PUR_GROUP": "X", "SUPPL_PLNT": "X",
    "_note": "MANDATORY. Every field set in POHEADER needs its X flag here. Miss one and the BAPI IGNORES that value SILENTLY - no error is raised. This is the single most common cause of a BAPI call that appears to work and does nothing."
  },

  "POITEM": [
    { "PO_ITEM": "00010", "MATERIAL": "<material>", "PLANT": "<receiving plant>", "ITEM_CAT": "7", "QUANTITY": "1", "PO_UNIT": "EA" }
  ],
  "POITEMX": [
    { "PO_ITEM": "00010", "MATERIAL": "X", "PLANT": "X", "ITEM_CAT": "X", "QUANTITY": "X", "PO_UNIT": "X" }
  ],

  "TESTRUN": "X",
  "_commit": "TESTRUN=X simulates. For a real create, TESTRUN must be blank AND the caller must issue BAPI_TRANSACTION_COMMIT. This BAPI does NOT commit on its own.",

  "_not_passable": "EKPV (shipping data: VSTEL, ROUTE, KUNNR, VSART, VSBED) has NO table in this BAPI. SAP derives it from the plant, the plant-customer assignment and route determination. Do not spec it as input."
}

{
  "_comment": "RFC module. Not callable from Postman.",
  "_evidence": "Executed twice on DS4 2026-08-19 as REAL WRITES. Run 1 without commit: returned TRANSPORT=1000 and 'S VW 488 Save shipment' - but VTTK had 0 rows, the document did NOT exist. Run 2 with BAPI_TRANSACTION_COMMIT in the same LUW: TRANSPORT=1001, VTTK had 1 row.",

  "HEADERDATA": {
    "SHIPMENT_TYPE":  "0001",
    "TRANS_PLAN_PT":  "0001"
  },

  "_commit_hazard": "THE CALLER OWNS THE COMMIT. The shipment number is allocated BEFORE commit. An uncommitted call therefore returns a success message AND a real-looking document number for a document that does not exist, and burns a number-range value doing it. DS4 number 1000 is permanently gone. Never treat RETURN-TYPE='S' plus a populated TRANSPORT field as proof of persistence - read the document back.",

  "_warning_not_error": "W VW 094 (deliveries missing) is a WARNING. A header-only shipment is accepted."
}

{
  "_comment": "RFC module. Not callable from Postman.",
  "_evidence": "Executed on DS4 2026-08-19 with TESTRUN=X. Single RETURN row: 'E M7 053 Posting only possible in periods 1998/03 and 1998/02 in company code 0001'. The call REACHED period control, which means GM_CODE=01 and the item structure were NOT rejected. Blocker is the MM period, not valuation. Also establishes plant PLQ3 -> company code 0001.",

  "GOODSMVT_CODE": { "GM_CODE": "01" },
  "_gm_code": "01 = MB01 goods receipt for purchase order, from T158G. Still a CANDIDATE for CNF - reaching period control does not prove it is the right code for this business step.",

  "GOODSMVT_HEADER": { "PSTNG_DATE": "19.08.2026", "DOC_DATE": "19.08.2026" },

  "GOODSMVT_ITEM": [
    { "MATERIAL": "<material>", "PLANT": "<plant>", "STGE_LOC": "<storage location>", "MOVE_TYPE": "101", "ENTRY_QNT": "1", "ENTRY_UOM": "EA" }
  ],

  "TESTRUN": "X",
  "_commit": "Commit behaviour for this BAPI is NOT yet proven. Do not assume it matches BAPI_SHIPMENT_CREATE. Test it explicitly before relying on it."
}

{
  "_comment": "RFC module. Not callable from Postman.",
  "WAIT": "X",
  "_evidence": "Executed once on DS4 in the same SE37 test sequence as BAPI_SHIPMENT_CREATE. Persisted shipment 1001 to VTTK.",
  "_scope": "Commit ownership is proven FOR BAPI_SHIPMENT_CREATE ONLY. Every other module must be tested individually - commit behaviour is per-module and empirical, and the defaults are not consistent."
}
